import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        List<Long> s_list = new ArrayList<>();
        List<Long> t_list = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            s_list.add(1L);
            t_list.add(1L);
        }

        for (int m = 1; m <= n; m++) {
            long sum_value = 0;
            for (int k = 0; k < m; k++) {
                sum_value += s_list.get(m - 1 - k) * s_list.get(k);
            }
            s_list.set(m, sum_value);
        }

        for (int h_iter = 0; h_iter < h; h_iter++) {
            List<Long> temp_t = new ArrayList<>();
            for (int m = 0; m <= n; m++) {
                long sum_val = 0;
                for (int k = 0; k < m; k++) {
                    sum_val += (s_list.get(k) - t_list.get(k)) * t_list.get(m - 1 - k)
                            + s_list.get(m - 1 - k) * t_list.get(k);
                }
                temp_t.add(sum_val);
            }
            t_list = temp_t;
        }

        System.out.println(t_list.get(n));
        scanner.close();
    }
}
